@Feature("workout-display-preferences.settings.failed-load-offers-retry")
fun `a failed load offers an in-place retry that clears once it succeeds`() =
    runTest {
        val api = FakeWorkoutApi()
        api.preferencesResult = Result.failure(RuntimeException("boom"))
        val state = SettingsState(api, NotificationState())

        state.load()
        assertTrue(state.loadFailed)

        api.preferencesResult = Result.success(WorkoutPreferences(displayUnit = WeightUnit.LBS))
        state.load()

        assertFalse(state.loadFailed)
        assertEquals(WeightUnit.LBS, state.displayUnit)
    }

