@Feature("workout-display-preferences.settings.no-confirmed-value-no-invented-revert")
fun `a failed write with nothing ever confirmed leaves the control alone and offers retry instead of guessing`() =
    runTest {
        // The mount's own load fails too, so nothing has ever been confirmed by the time the
        // write is refused — the exact precondition the old hardcoded `confirmedUnit = KG` got
        // wrong by pretending KG had been confirmed when it had not.
        val api = FakeWorkoutApi()
        api.preferencesResult = Result.failure(RuntimeException("network down"))
        val notifications = NotificationState()
        val state = SettingsState(api, notifications)
        state.load()
        assertTrue(state.loadFailed)

        api.updatePreferencesResult = Result.failure(RuntimeException("boom"))
        state.chooseUnit(WeightUnit.LBS)

        // No confirmed value exists to revert to, so the optimistic choice stays on screen
        // rather than snapping back to a value the server never actually confirmed.
        assertEquals(WeightUnit.LBS, state.displayUnit)
        assertTrue(state.loadFailed)
        assertTrue(notifications.current!!.isFailure)
    }

